insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000020', 'en', null, 'Introduction to Anthropology', 'A first tour of what it means to study humanity across time and cultures — the four fields, ethnography, language, human evolution, and the material past. Structure adapted from OpenStax Introduction to Anthropology (CC BY 4.0), with an emphasis on cultural relativism and avoiding ethnocentrism.', null, 'foundations', 32, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000020', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Anthropology is best defined as the study of…","options":["ancient ruins only","humanity across time and cultures","human anatomy only","foreign languages"],"answer":1,"explanation":"Anthropology studies humans holistically — biology, culture, language, and the past. See ''What is anthropology?''."},{"prompt":"Which is NOT one of anthropology''s four fields?","options":["cultural anthropology","linguistic anthropology","economic forecasting","biological anthropology"],"answer":2,"explanation":"The four fields are cultural, linguistic, biological, and archaeology — see ''The four fields''."},{"prompt":"The signature research method of cultural anthropology is…","options":["the laboratory experiment","ethnographic fieldwork","the national census","carbon dating"],"answer":1,"explanation":"Cultural anthropologists use long-term participant observation — see ''Ethnography''."},{"prompt":"Judging another culture only by the standards of your own is called…","options":["cultural relativism","holism","ethnocentrism","fieldwork"],"answer":2,"explanation":"Ethnocentrism is the bias anthropology works to overcome — see ''The four fields''."},{"prompt":"Understanding a practice within its own cultural context is called…","options":["ethnocentrism","cultural relativism","excavation","natural selection"],"answer":1,"explanation":"Cultural relativism is a method for understanding, not for suspending all judgment — see ''Ethnography''."},{"prompt":"Studying how humans evolved from earlier primates falls under…","options":["archaeology","linguistic anthropology","biological anthropology","cultural anthropology"],"answer":2,"explanation":"Human evolution is a core topic in biological anthropology — see ''Human evolution''."},{"prompt":"Archaeologists mainly learn about the past by studying…","options":["living informants","written laws","material remains and artifacts","genetic samples only"],"answer":2,"explanation":"Archaeology reconstructs past life from material culture — see ''Material culture''."},{"prompt":"A system that organizes people by descent, marriage, and family ties is called…","options":["a kinship system","an artifact","a phoneme","a fossil"],"answer":0,"explanation":"Kinship is a central way societies organize social life — see ''Cultural anthropology''."}]}'::jsonb, null, 10),
  (2, 'What anthropology is: the four fields', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name anthropology''s four fields and explain why the discipline is *holistic*. Warm-up: from the diagnostic, which field would study a 10,000-year-old tool, and which would study a living community''s marriage customs?"},{"heading":"The idea","text":"Anthropology is the study of humanity in the widest possible sense — across all times and all cultures. In North America it is traditionally organized into *four fields*: *cultural anthropology* (how living people make meaning and organize social life), *linguistic anthropology* (how language shapes and reflects culture), *biological anthropology* (humans as evolving biological organisms), and *archaeology* (the human past read through material remains). Tying them together is *holism* — the commitment to seeing any part of human life in relation to the whole. The discipline''s core discipline of mind is fighting *ethnocentrism*, the habit of judging others by your own culture''s standards, by practicing *cultural relativism*: understanding a practice first within its own context."},{"heading":"Worked example","text":"Imagine four anthropologists meeting the same community. The cultural anthropologist lives there and asks how families share food; the linguistic anthropologist records how greetings change by age and status; the biological anthropologist studies diet and health; the archaeologist digs an old hearth to see what people ate centuries ago. Four lenses, one shared question: what does it mean to be human here?"},{"heading":"Your turn","text":"Match each question to a field: (1) ''How did this population adapt to high altitude?'' (2) ''What do burial goods tell us about a vanished society?'' (3) ''How do speakers signal respect?'' (4) ''How is authority shared in this village today?'' Answers: 1-biological, 2-archaeology, 3-linguistic, 4-cultural."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking cultural relativism means ''anything goes'' — it is a tool for *understanding* before judging, not a ban on all ethics. Mistake: assuming anthropology only studies distant or ''exotic'' peoples — it studies every human society, including your own. Exit: (a) Name the four fields. (b) What bias does cultural relativism counter? Answers: cultural, linguistic, biological, archaeology; ethnocentrism."}]}'::jsonb, 'Keep two words handy all course: ethnocentrism (the bias) and cultural relativism (the fix).', 12),
  (3, 'Cultural anthropology and ethnography', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what ethnographic fieldwork is and why anthropologists seek an insider''s point of view. Warm-up: what is the signature method of cultural anthropology?"},{"heading":"The idea","text":"*Culture* is the learned, shared set of meanings, practices, and values that a group passes on — not something people are born with, but something they grow into. Cultural anthropologists study it through *ethnography*: long-term, close-up research in the flow of everyday life. The main technique is *participant observation* — living alongside people, joining daily activities while carefully observing and recording. The goal is the *emic* (insider''s) perspective: understanding how life makes sense from within, rather than imposing an *etic* (outsider''s) frame too quickly. Cultural relativism is the working stance that keeps the researcher from mistaking ''different'' for ''wrong.''"},{"heading":"Worked example","text":"Suppose you observe a community where guests are always offered food they must at first politely refuse. An ethnocentric read: ''They are being insincere.'' An ethnographic read: you stay, you watch, you ask — and learn that the refuse-then-accept exchange is a shared script that lets both host and guest show respect. Same behavior, opposite conclusions; only patient fieldwork gets the emic meaning."},{"heading":"Your turn","text":"Label each as emic or etic: (1) a resident explaining ''we fast to honor our ancestors,'' (2) a visitor measuring calorie intake during the fast, (3) a resident describing who may enter a sacred space, (4) an outsider ranking the ritual as ''irrational.'' Answers: 1-emic, 2-etic, 3-emic, 4-etic (and ethnocentric)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating your own culture as the neutral ''normal'' against which others are measured — it is one culture among many. Mistake: thinking a quick visit equals ethnography; fieldwork takes sustained time to earn trust and context. Exit: (a) What method defines cultural anthropology? (b) Does ''emic'' mean the insider''s or the outsider''s view? Answers: participant observation / ethnography; the insider''s."}]}'::jsonb, 'Ethno- means ''people/culture''; -graphy means ''writing.'' Ethnography = writing about a people.', 13),
  (4, 'Language and communication', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe what linguistic anthropology studies and how language and culture shape each other. Warm-up: which of the four fields records how greetings change with a speaker''s status?"},{"heading":"The idea","text":"*Linguistic anthropology* studies language as a social and cultural practice, not just a grammar. Every human language is fully expressive and rule-governed — there are no ''primitive'' languages. Anthropologists examine how people actually use speech: how word choice signals politeness, gender, age, or authority; how *linguistic relativity* suggests the categories a language offers can nudge how speakers notice the world; and how communities keep or lose languages under social pressure. A key idea is that language does things — a promise, a greeting, or a naming ceremony performs an action, it doesn''t merely describe one."},{"heading":"Worked example","text":"In many languages there are separate ''you'' forms for a close friend versus an elder or superior. Choosing the wrong one is grammatically fine but socially loud — it can read as warmth or as disrespect. A linguistic anthropologist notes that the choice encodes the whole social relationship in a single pronoun, something a dictionary definition alone would miss."},{"heading":"Your turn","text":"Decide whether each shows language *doing* something social: (1) saying ''I now pronounce you married,'' (2) reciting the alphabet, (3) using a respectful title for an elder, (4) naming a newborn in a ceremony. Answers: 1-yes (performs the marriage), 2-no (just reciting), 3-yes (marks respect/status), 4-yes (confers identity)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: ranking languages or dialects as ''better'' or ''broken'' — that is linguistic ethnocentrism; all natural varieties are systematic. Mistake: assuming a word maps neatly onto one word in another language; meanings are shaped by cultural context. Exit: (a) True or false: some human languages are too simple to express abstract ideas. (b) Name one thing pronoun choice can signal. Answers: false; politeness/status/relationship."}]}'::jsonb, 'Linguistic anthropology asks not just ''what do words mean?'' but ''what does using them *do*?''', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Holism in anthropology means…","options":["studying only whole skeletons","seeing each part of human life in relation to the whole","avoiding fieldwork","focusing on one culture forever"],"answer":1,"explanation":"Holism connects biology, culture, language, and the past."},{"prompt":"The insider''s point of view is called the…","options":["etic perspective","emic perspective","ethnocentric view","fossil record"],"answer":1,"explanation":"Emic = insider; etic = outsider."},{"prompt":"Participant observation is central to which field?","options":["archaeology","biological anthropology","cultural anthropology","geology"],"answer":2,"explanation":"It is the signature method of ethnographic fieldwork."},{"prompt":"Calling another group''s language ''broken'' or ''primitive'' is an example of…","options":["cultural relativism","holism","linguistic ethnocentrism","participant observation"],"answer":2,"explanation":"All natural languages are fully systematic; ranking them is ethnocentric."},{"prompt":"Culture is best described as…","options":["something people are born with","learned and shared within a group","the same everywhere","purely genetic"],"answer":1,"explanation":"Culture is learned and transmitted, not inherited biologically."},{"prompt":"Saying ''I now pronounce you married'' illustrates that language can…","options":["only describe events","perform an action","never change meaning","replace fieldwork"],"answer":1,"explanation":"Some utterances do something social rather than merely describe."}]}'::jsonb, null, 8),
  (6, 'Biological anthropology and human evolution', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what biological anthropology studies and outline how natural selection shapes human evolution. Warm-up: which field would study how a population adapted to high altitude?"},{"heading":"The idea","text":"*Biological anthropology* studies humans as biological beings — our evolution, our variation, and our closest living relatives, the other primates. The engine of evolution is *natural selection*: within a population, individuals vary; some inherited traits improve survival and reproduction in a given environment; those traits become more common over generations. Humans belong to the *hominin* line; the fossil and genetic record shows a gradual mosaic of changes — upright walking (*bipedalism*), changing teeth and diet, and later larger brains. Crucially, human ''races'' are not biologically distinct categories: human genetic variation is largely continuous and does not map onto the social labels cultures invent."},{"heading":"Worked example","text":"Take lactase persistence — the ability to digest milk into adulthood. In populations with a long history of dairying, individuals who could digest milk had a nutritional edge, so the trait spread; in populations without that history, it stayed rare. Same species, different local selection pressures, different outcomes — evolution acting on a population, not a choice made by any person."},{"heading":"Your turn","text":"True or false: (1) An individual antelope evolves longer legs by running a lot. (2) Bipedalism is a hominin trait. (3) Biological ''races'' are sharp, discrete genetic categories. (4) Natural selection acts on inherited variation. Answers: 1-false (populations evolve, not individuals through effort), 2-true, 3-false, 4-true."},{"heading":"Common mistakes & exit ticket","text":"Mistake: saying humans ''come from'' modern monkeys — we share common ancestors with other primates, we are not descended from living ones. Mistake: treating evolution as ''improvement toward a goal''; it is adaptation to particular environments. Exit: (a) What is the engine of evolutionary change? (b) True or false: human races are discrete biological types. Answers: natural selection; false."}]}'::jsonb, 'Evolution is about populations changing over generations — never about an individual ''trying'' to change.', 13),
  (7, 'Archaeology and material culture', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how archaeologists reconstruct past human life from material remains, and why context is everything. Warm-up: which field learns about the past mainly through artifacts rather than living informants?"},{"heading":"The idea","text":"*Archaeology* studies the human past through *material culture* — the physical things people made, used, and left behind: tools, pottery, buildings, food remains, and *features* like hearths or post-holes. Because most of the human story was never written down, these traces are our main evidence. Two ideas are central. First, *context*: an object''s meaning comes from where and with what it was found (its *provenience*), so careful, layered excavation and recording matter more than the object''s beauty. Second, *stratigraphy*: in undisturbed ground, deeper usually means older, letting archaeologists build a timeline. Interpretation stays cautious and comparative, and it resists reading the past through present-day assumptions."},{"heading":"Worked example","text":"A plain clay pot found *in place* beside a hearth, charred seeds, and grinding stones tells a rich story: cooking, diet, daily labor. The same pot ripped from the ground and sold loses its provenience — now it is just an object with no story. That is why looting destroys knowledge even when the artifact survives."},{"heading":"Your turn","text":"Label each as an artifact, a feature, or neither: (1) a chipped stone blade, (2) a fire pit dug into the soil, (3) a naturally rounded river pebble, (4) a post-hole marking a vanished wall. Answers: 1-artifact, 2-feature, 3-neither (unmodified nature), 4-feature."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming the ''best'' finds are the prettiest — a humble seed or ash layer can outweigh a jewel for understanding daily life. Mistake: judging past peoples as ''primitive'' because their tools look simple; that is ethnocentrism aimed at the past. Exit: (a) What word names where and with what an object was found? (b) In undisturbed layers, deeper usually means what? Answers: provenience (context); older."}]}'::jsonb, 'An artifact is made or modified by people; context (where it was found) matters as much as the object.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"ethnocentrism","translation":"judging another culture only by the standards of your own","example":"Calling an unfamiliar custom ''weird'' without context is ethnocentrism."},{"term":"cultural relativism","translation":"understanding a practice within its own cultural context before judging it","example":"Cultural relativism asks ''what does this mean to them?'' first."},{"term":"ethnography","translation":"long-term, close-up fieldwork studying a living community, and the writing it produces","example":"Her ethnography of a fishing village took two years of participant observation."},{"term":"holism","translation":"the anthropological commitment to studying human life as an interconnected whole","example":"Holism links a society''s diet, language, and history."},{"term":"natural selection","translation":"the process by which inherited traits that aid survival and reproduction become more common over generations","example":"Natural selection favored milk digestion in dairying populations."},{"term":"material culture","translation":"the physical objects and remains people make and leave behind, studied by archaeology","example":"Pottery and tools are material culture that reveal daily life."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Natural selection acts on…","options":["an individual''s effort","inherited variation within a population","written records","artifacts"],"answer":1,"explanation":"Populations evolve as heritable traits shift over generations."},{"prompt":"In undisturbed archaeological layers, deeper generally means…","options":["newer","older","richer","no relationship"],"answer":1,"explanation":"Stratigraphy: lower layers are usually earlier."},{"prompt":"A fire pit dug into ancient soil is best classified as a…","options":["portable artifact","feature","fossil","language"],"answer":1,"explanation":"Features are non-portable traces of human activity."},{"prompt":"Human biological ''races'' are…","options":["sharp, discrete genetic categories","not distinct biological types; variation is largely continuous","determined by language","the same as cultures"],"answer":1,"explanation":"Human genetic variation does not map onto social race labels."},{"prompt":"The value of an artifact for archaeology depends most on its…","options":["beauty","market price","context (provenience)","size"],"answer":2,"explanation":"Where and with what it was found gives it meaning."},{"prompt":"Bipedalism refers to…","options":["a large brain","walking upright on two legs","tool use","spoken language"],"answer":1,"explanation":"Upright walking is an early hominin trait."}]}'::jsonb, null, 8),
  (10, 'Applied project: a mini-ethnography', 'writing', '{"sections":[{"heading":"The task","text":"Do a small ethnography of a group or place you already know well — a team, a workplace break room, a family meal, a gaming group, a corner shop. You will not run a full study; you will practice observing like an anthropologist and, above all, practice *cultural relativism* toward a setting you might otherwise take for granted."},{"heading":"Milestones","text":"1) Pick your group/place and write one clear question about how it works (e.g. ''How do newcomers learn the unwritten rules here?''). 2) Do 20–30 minutes of participant observation and take field notes: who does what, in what order, using which words. 3) Describe one shared practice and give its *emic* meaning — what it means to the people, not just how it looks to an outsider. 4) Name one moment where you caught yourself judging by your own standards, and rewrite that judgment relativistically."},{"heading":"Self-check rubric","text":"✔ Your question is specific and answerable through observation. ✔ Your notes describe behavior concretely enough that a stranger could picture it. ✔ You gave an insider (emic) meaning, not just an outsider''s reaction. ✔ You identified and corrected at least one ethnocentric judgment, showing cultural relativism in action. If all four are true, you''ve done fieldwork like an anthropologist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000020' and l.position = v.pos
);
